use crate::*;
fn roof_item(i:&Value)->bool{["Roof","Roof framing","Roof ventilation"].contains(&s(i,"category"))||["ziproof","atticinsulation","baffles","attichatch"].contains(&s(i,"id"))}
fn one_system(id:&str)->bool{["ziproller","facade","waterheater","waterheaterkit","watermainkit","servicepanel","grounding","wholehousevent"].contains(&id)}
pub fn build(c:&Config)->Value{if c.stories==1{return model::build_level(c)}let blank=c.design_mode=="Blank slate";let hole=if !blank||stairs::custom(c).is_some(){96.}else{0.};let top=c.stories-1;let decks=top as f64;let mut levels=vec![];for floor in 0..c.stories{let mut cc=c.clone();cc.active_floor=floor;levels.push(model::build_level(&cc));}let mut out=levels[c.active_floor].clone();let mut items:BTreeMap<String,Value>=BTreeMap::new();for(floor,m)in levels.iter().enumerate(){for i in m["items"].as_array().unwrap(){let id=s(i,"id");if floor!=top&&roof_item(i)&&id!="roofboots"||floor>0&&(s(i,"category")=="Foundation"||one_system(id)){continue}let mut item=i.clone();let mut raw=n(i,"rawNet");if floor<top&&id=="drywallceiling"{raw-=hole/64.;}if floor>0{raw-=match id{"vinyl"=>hole,"adhesive"=>hole/600.,"floorleveler"=>hole/200.,_=>0.};}if floor<top{raw-=match id{"compound"=>hole/450.,"drywalltape"=>hole*0.35/500.,"drywallscrews"=>hole/1000.,"primer"=>hole/350.,"paint"=>hole*2./350.,_=>0.};}if let Some(old)=items.get_mut(id){old["rawNet"]=json!(n(old,"rawNet")+raw.max(0.));}else{item["rawNet"]=json!(raw.max(0.));items.insert(id.into(),item);}}}
 let gap=structural::floor_gap(c);let fh=c.wall_height+gap;let stair_info=stairs::info(c,&levels[0]["rooms"],fh);let opening=&stair_info["opening"];let(sx,sz,sw,sd)=(n(opening,"x"),n(opening,"z"),n(opening,"w"),n(opening,"d"));let risers=n(&stair_info,"risers")as usize;let stair_style=stairs::style(c);let spiral=stair_style=="Spiral";let treads=risers.saturating_sub(2);let ground_walls:Vec<Wall>=serde_json::from_value(levels[0]["walls"].clone()).unwrap();let product=structural::floor_design(c,&ground_walls).product;let depth=16./12.;let flange=product.map_or(0.25,|p|p.flange/12.);let mut members=vec![];let mut num=0;let mut add_member=|role:&str,mat:&str,a:[f64;3],b:[f64;3],width:f64,depth:f64|{let length=((a[0]-b[0]).powi(2)+(a[1]-b[1]).powi(2)+(a[2]-b[2]).powi(2)).sqrt();if length<0.1{return}num+=1;members.push(json!({"id":format!("FLOOR-{}",num),"wallId":"FLOOR","role":role,"material":mat,"group":"Floor framing","x1":a[0],"y1":a[1],"z1":a[2],"x2":b[0],"y2":b[1],"z2":b[2],"width":width,"depth":depth,"length":length,"stockLength":(length/2.).ceil()*2.}));};
 for deck in 0..top{let below:Vec<Wall>=serde_json::from_value(levels[deck]["walls"].clone()).unwrap();let structural::Deck{along,spans,girders,..}=structural::floor_design(c,&below);let joist_y=fh*(deck+1)as f64-0.25-depth/2.;
 // Flush girders under the floor-panel joints, broken at the stair opening; posts down to the floor below.
 let floor_y=fh*deck as f64;for &x in &girders{let crosses=hole>0.&&x>sx+0.001&&x<sx+sw-0.001;let runs=if crosses{vec![(0.,sz),(sz+sd,c.depth)]}else{vec![(0.,c.depth)]};for(a,b)in runs{add_member("Floor support beam","LVL flush girder",[x,joist_y,a],[x,joist_y,b],0.4375,depth);}
  for z in structural::girder_posts(c){if !(crosses&&z>sz-0.001&&z<sz+sd+0.001){add_member("Girder post","LVL post",[x,floor_y,z],[x,joist_y-depth/2.,z],0.4375,0.4375);}}}
 for span in &spans{let station=n(span,"station");let(a,b)=(n(span,"start"),n(span,"end"));let(lo,hi,cross_lo,cross_hi)=if along{(sx,sx+sw,sz,sz+sd)}else{(sz,sz+sd,sx,sx+sw)};let parts=if hole>0.&&station>cross_lo+0.001&&station<cross_hi-0.001{vec![(a,b.min(lo)),(a.max(hi),b)]}else{vec![(a,b)]};for(a,b)in parts{if b>a+0.1{let pa=if along{[a,joist_y,station]}else{[station,joist_y,a]};let pb=if along{[b,joist_y,station]}else{[station,joist_y,b]};add_member("Floor I-joist","I-joist",pa,pb,flange,depth);}}}
 for z in [0.,c.depth]{add_member("Rim board","LSL rim board",[0.,joist_y,z],[c.width,joist_y,z],0.125,depth);}
 for x in [0.,c.width]{add_member("Rim board","LSL rim board",[x,joist_y,0.],[x,joist_y,c.depth],0.125,depth);}
 if hole>0.{for z in [sz,sz+sd]{add_member("Stair opening header","LVL",[sx,joist_y,z],[sx+sw,joist_y,z],0.29,depth);}
 for x in [sx,sx+sw]{add_member("Stair opening trimmer","LVL",[x,joist_y,sz],[x,joist_y,sz+sd],0.29,depth);}}}
 for member in &mut members{if s(member,"role")=="Floor I-joist"{member["material"]=json!(product.map_or("I-joist · sizing pending".to_string(),|p|format!("{} · {:.3} in · preliminary",p.series,p.depth)));}} let mut extra=model::Takeoff{items:vec![],c};let mut stocks:BTreeMap<usize,usize>=BTreeMap::new();for m in members.iter().filter(|m|s(m,"role")=="Floor I-joist"){*stocks.entry(n(m,"stockLength")as usize).or_default()+=1;}for(len,count)in stocks{extra.add(&format!("floorjoist{}",len),"Floor framing",&format!("Floor I-joists · {} · {:.3} in · {} ft stock",product.map_or("Sizing pending",|p|p.series),depth*12.,len),count as f64,"pieces",len as f64*product.map_or(6.5,|p|p.rate),"Actual 16-in stations and proposed bearing-wall spans, interrupted at the stair opening. Preliminary TJ-4000 uniform-load table candidate; final capacity and load path pending.","Modeled count",true,true);}
 for(role,id,rate)in[("Rim board","floorrim",6.),("Stair opening header","stairheaders",28.),("Stair opening trimmer","stairtrimmers",28.),("Floor support beam","floorbeams",36.),("Girder post","girderposts",14.)]{extra.add(id,"Floor framing",role,members.iter().filter(|m|s(m,"role")==role).map(|m|n(m,"length")).sum(),"linear ft",rate,"Enumerated floor frame geometry. Beam/post load paths and connections require engineering.","Modeled geometry",true,false);}
 for(id,name,net,unit,price,whole)in[("subfloor","23/32 in AdvanTech T&G panels · 4 × 8 ft",decks*(c.width*c.depth-hole)/32.,"sheets",59.,true),("floorhangers","Floor joist bearing / hanger sets",stocks_len(&members)*2.,"sets",18.,true),("floorblocking","Floor blocking / web stiffeners",stocks_len(&members)*2.,"sets",6.,true),("subfloorscrews","Subfloor screw packs · 1,000",decks*(c.width*c.depth-hole)*2.5/1000.,"packs",65.,true),("subfloorglue","Subfloor adhesive · 28 oz",decks*(c.width*c.depth-hole)/48.,"tubes",8.,true),("stairtreads","Stair treads · 3.5 ft",if spiral{0.}else{decks*(treads+usize::from(stair_style=="Straight"))as f64},"pieces",38.,true),("stairrisers","Stair risers · 3.5 ft",if spiral{0.}else{decks*risers as f64},"pieces",20.,true),("stairstringers","Engineered stair stringer blanks",decks*match stair_style{"Straight"=>3.,"L-shaped"=>5.,"Spiral"=>0.,_=>6.},"pieces",110.,true),("stairlanding","Stair landing framing / decking",decks*match stair_style{"Straight"|"Spiral"=>0.,"L-shaped"=>3.5*3.5,_=>8.*4.},"sq ft",12.,false),("stairspiral","Spiral stair kit · steel, 7 ft diameter, with rail",if spiral{decks}else{0.},"kits",4200.,true),("stairrail","Stair handrail / upper guard assemblies",decks*(2.*((treads as f64*10./12./2.).powi(2)+(fh/2.).powi(2)).sqrt()+16.),"linear ft",45.,false),("floorfireblock","Inter-story fireblocking / draftstop material",decks*2.*(c.width+c.depth),"linear ft",2.,false)]{let net=if hole==0.&&["stairstringers","stairlanding","stairrail"].contains(&id){0.}else{net};extra.add(id,"Floor framing",name,net,unit,price,"Stair and floor allowance per upper story from modeled geometry. Final product, support and connection details pending.","Allowance",true,whole);}
 for i in extra.items{let v=serde_json::to_value(i).unwrap();items.insert(s(&v,"id").into(),v);}
 let mut subtotal=0.;let mut cats:BTreeMap<String,f64>=BTreeMap::new();let mut final_items=vec![];for(_,mut i)in items{let raw=n(&i,"rawNet");let amount=raw*(1.+n(&i,"wastePercent")/100.);let qty=if s(&i,"rounding")=="Whole purchase units"{(amount-1e-9).max(0.).ceil()}else{round(amount)};let total=round(qty*n(&i,"price"));i["net"]=json!(round(raw));i["qty"]=json!(qty);i["total"]=json!(total);subtotal+=total;*cats.entry(s(&i,"category").into()).or_default()+=total;final_items.push(i);}
 out["items"]=json!(final_items);out["subtotal"]=json!(round(subtotal));let tax=round(subtotal*c.tax/100.);out["tax"]=json!(tax);out["total"]=json!(round(subtotal+tax));out["categoryTotals"]=json!(cats);
 for key in ["partitionLength","claddingArea","drywallWalls","cavityArea","wallpaperArea","wallpaperBedroomArea","wallpaperGeneralArea","bedroomWallArea","generalWallArea","trimSurfaceArea"]{out[key]=json!(round(levels.iter().map(|m|n(m,key)).sum()));}
 out["area"]=json!(c.width*c.depth*c.stories as f64-hole*decks+wings::all(c).iter().map(|g|g.w*g.d).sum::<f64>());out["footprintArea"]=json!(c.width*c.depth);out["drywallCeiling"]=json!(c.width*c.depth*c.stories as f64-hole*decks);out["drywallTotal"]=json!(round(n(&out,"drywallWalls")+n(&out,"drywallCeiling")));out["roofArea"]=levels[top]["roofArea"].clone();out["roof"]=levels[top]["roof"].clone();out["ventilation"]=levels[top]["ventilation"].clone();out["rafters"]=levels[top]["rafters"].clone();
 let keys:Vec<_>=out["counts"].as_object().unwrap().keys().cloned().collect();for key in keys{out["counts"][&key]=json!(if key=="rafters"{n(&levels[top]["counts"],&key)}else if key=="drywallSheets"{final_items.iter().filter(|i|s(i,"id").starts_with("drywall")&&s(i,"unit")=="sheets").map(|i|n(i,"qty")).sum()}else{levels.iter().map(|m|n(&m["counts"],&key)).sum()});}

 for m in &mut levels{m["stair"]=stair_info.clone();m["floorFrameMembers"]=json!(members);}out["floorHeight"]=json!(fh);out["floorGap"]=json!(gap);out["stair"]=stair_info;out["floorFrameMembers"]=json!(members);
 for key in ["frameMembers","walls","rooms","openings","furniture","spans"]{out[format!("all{}{}",key[..1].to_uppercase(),&key[1..])]=json!(levels.iter().flat_map(|m|m[key].as_array().unwrap().iter().map(move|v|{let mut v=v.clone();v["floorIndex"]=m["floorIndex"].clone();v})).collect::<Vec<_>>());}
 let mut roles:BTreeMap<String,u64>=BTreeMap::new();for m in &levels{for(k,v)in m["piecesByRole"].as_object().unwrap(){*roles.entry(k.clone()).or_default()+=v.as_u64().unwrap_or(0);}}out["piecesByRole"]=json!(roles);let mut notes=vec![];for m in &levels{for note in m["stagingNotes"].as_array().unwrap(){notes.push(format!("Floor {}: {}",n(m,"floorIndex")+1.,note.as_str().unwrap_or("")));}}out["stagingNotes"]=json!(notes);let electric=levels.iter().map(|m|n(&m["electrical"],"total")).sum::<f64>();out["electrical"]["total"]=json!(electric);out["electrical"]["interior"]=json!(electric-2.);out["electrical"]["exterior"]=json!(2);out["electrical"]["schedule"]=json!(levels.iter().flat_map(|m|m["electrical"]["schedule"].as_array().unwrap().iter().map(move|e|{let mut e=e.clone();e["room"]=json!(format!("Floor {} · {}",n(m,"floorIndex")+1.,s(&e,"room")));e})).collect::<Vec<_>>());out["openingChecks"]["issues"]=json!(levels.iter().flat_map(|m|m["openingChecks"]["issues"].as_array().unwrap().clone()).collect::<Vec<_>>());out["openingChecks"]["allHeightGuardrailsPass"]=json!(levels.iter().all(|m|m["openingChecks"]["allHeightGuardrailsPass"]==true));out["allTrimOrnaments"]=json!(levels.iter().flat_map(|m|m["trimOrnaments"].as_array().cloned().unwrap_or_default()).collect::<Vec<_>>());out["allTrimPieces"]=json!(levels.iter().flat_map(|m|m["trimPieces"].as_array().cloned().unwrap_or_default()).collect::<Vec<_>>());let schedule=levels.iter().flat_map(|m|m["openingChecks"]["schedule"].as_array().unwrap().clone()).collect::<Vec<_>>();out["openingChecks"]["schedule"]=json!(schedule);out["accessibility"]["allIssues"]=json!(levels.iter().flat_map(|m|m["accessibility"]["issues"].as_array().unwrap().iter().map(move |v|format!("Floor {} · {}",n(m,"floorIndex")+1.,v.as_str().unwrap_or("")))).collect::<Vec<_>>());out["levels"]=json!(levels);out
}
fn stocks_len(ms:&[Value])->f64{ms.iter().filter(|m|s(m,"role")=="Floor I-joist").count()as f64}
